describe('Data Refresh After Mutation', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
    });

    it('should refresh data automatically after a successful mutation', () => {
        // Assuming there's a button to trigger the mutation
        cy.intercept('POST', '/api/mutate', { statusCode: 200 }).as('mutateData');

        cy.get('[data-cy=mutate-button]').click(); // Replace with the actual selector for the mutation button
        cy.wait('@mutateData');

        // Check if the data has been refreshed
        cy.get('[data-cy=data-container]').should('contain', 'Updated Data'); // Replace with actual expected data
    });

    it('should not refresh data if the mutation fails', () => {
        cy.intercept('POST', '/api/mutate', { statusCode: 500 }).as('mutateDataFail');

        cy.get('[data-cy=mutate-button]').click(); // Replace with the actual selector for the mutation button
        cy.wait('@mutateDataFail');

        // Check that the data remains unchanged
        cy.get('[data-cy=data-container]').should('not.contain', 'Updated Data'); // Replace with actual expected data
    });
});
